<?php
 namespace Slim; class Router { protected $currentRoute; protected $routes; protected $namedRoutes; protected $matchedRoutes; protected $routeGroups; public function __construct() { $this->routes = array(); $this->routeGroups = array(); } public function getCurrentRoute() { if ($this->currentRoute !== null) { return $this->currentRoute; } if (is_array($this->matchedRoutes) && count($this->matchedRoutes) > 0) { return $this->matchedRoutes[0]; } return null; } public function getMatchedRoutes($httpMethod, $resourceUri, $reload = false) { if ($reload || is_null($this->matchedRoutes)) { $this->matchedRoutes = array(); foreach ($this->routes as $route) { if (!$route->supportsHttpMethod($httpMethod) && !$route->supportsHttpMethod("ANY")) { continue; } if ($route->matches($resourceUri)) { $this->matchedRoutes[] = $route; } } } return $this->matchedRoutes; } public function map(\Slim\Route $route) { list($groupPattern, $groupMiddleware) = $this->processGroups(); $route->setPattern($groupPattern . $route->getPattern()); $this->routes[] = $route; foreach ($groupMiddleware as $middleware) { $route->setMiddleware($middleware); } } protected function processGroups() { $pattern = ""; $middleware = array(); foreach ($this->routeGroups as $group) { $k = key($group); $pattern .= $k; if (is_array($group[$k])) { $middleware = array_merge($middleware, $group[$k]); } } return array($pattern, $middleware); } public function pushGroup($group, $middleware = array()) { return array_push($this->routeGroups, array($group => $middleware)); } public function popGroup() { return (array_pop($this->routeGroups) !== null); } public function urlFor($name, $params = array()) { if (!$this->hasNamedRoute($name)) { throw new \RuntimeException('Named route not found for name: ' . $name); } $search = array(); foreach ($params as $key => $value) { $search[] = '#:' . preg_quote($key, '#') . '\+?(?!\w)#'; } $pattern = preg_replace($search, $params, $this->getNamedRoute($name)->getPattern()); return preg_replace('#\(/?:.+\)|\(|\)|\\\\#', '', $pattern); } public function addNamedRoute($name, \Slim\Route $route) { if ($this->hasNamedRoute($name)) { throw new \RuntimeException('Named route already exists with name: ' . $name); } $this->namedRoutes[(string) $name] = $route; } public function hasNamedRoute($name) { $this->getNamedRoutes(); return isset($this->namedRoutes[(string) $name]); } public function getNamedRoute($name) { $this->getNamedRoutes(); if ($this->hasNamedRoute($name)) { return $this->namedRoutes[(string) $name]; } return null; } public function getNamedRoutes() { if (is_null($this->namedRoutes)) { $this->namedRoutes = array(); foreach ($this->routes as $route) { if ($route->getName() !== null) { $this->addNamedRoute($route->getName(), $route); } } } return new \ArrayIterator($this->namedRoutes); } } 